KG42.register("source_edge_archive-4b6928d0d2ee80b85d132e4c",{"id":"15-multiagent_reverse_auction::v141-c-R007::E::v141-c-R007-E001","paper":"15-multiagent_reverse_auction","rule_id":"v141-c-R007","rule_ref":"15-multiagent_reverse_auction::v141-c-R007","record":{"edge_id":"v141-c-R007-E001","source":"clearing.local","target":"execution.energy_trade","type":"links","constraint_ids":["v141-c-R007-C001"],"evidence_ids":["v141-b-g01-E07","v141-b-g01-E20"]},"evidence_class":"S","provenance_gate":"direct_C_edge_with_constraint_and_source_excerpt","scientific_acceptance":false,"accepted_constraint_ids":["v141-c-R007-C001"],"held_constraint_ids":[],"semantic_review_status":"supported","source":"COMP-443a9bf9853dcd78","target":"COMP-efa6e37c97477e8a","source_occurrence_id":"15-multiagent_reverse_auction::v141-c-R007::V::clearing.local","target_occurrence_id":"15-multiagent_reverse_auction::v141-c-R007::V::execution.energy_trade","source_unit_id":"15-multiagent_reverse_auction::v141-a-M01::clearing.local","target_unit_id":"15-multiagent_reverse_auction::v141-a-M01::execution.energy_trade","omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"activation","context_text":"Actuator instructions implementing trades awarded through the microgrid's hour-ahead reverse auction. | Hourly reverse-auction dispatch to qualified DER bidders in the grid-connected microgrid. | Implementation of hourly allocations to qualified DER bidders in the grid-connected microgrid. | Purchase of qualified DER supply in the grid-connected microgrid's hour-ahead market when local supply is insufficient.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-E07","v141-b-g01-E20","v141-b-g01-E21"]},"active":true,"source_signature":"151c65034f18205363f5ffa3f05b6067b316fb24b699da7235fd09661058bd58","relation_scope":"original_occurrence_pair_only","internal_to_parent":false,"source_science":{"mechanism_id":"v141-a-M01","source_definition":"The local allocation process uses the qualified bidder's submitted supply to check whether that bidder can cover all demand. Scope: Hour-ahead allocation of the grid-connected microgrid's lumped demand among qualified DER bidders. The aggregator coordinates local procurement by buying the qualified amount of power from DERs, with the remaining demand purchased from the utility. Scope: Local DER procurement in the grid-connected microgrid's hour-ahead reverse auction under insufficient supply. Condition: Total supply is less than demand and some bidders participate in the auction. Local procurement aims to purchase the required amount of power at the lowest cost. Scope: Procurement objective for the microgrid's lumped load in the hour-ahead reverse auction. The first qualified bidder is supposed to cover the majority of the total demand. Scope: Demand allocation among qualified bidders in the hour-ahead reverse auction. The second qualifying bidder covers the remaining demand. Scope: Residual demand allocation among qualified bidders in the hour-ahead reverse auction. Condition: A supply deficit remains after the first qualified bidder's contribution.","target_definition":"Final local power allocations provide the power references according to which actuator agents operate generation units for the cleared exchange. Scope: Implementation of hourly allocations to qualified DER bidders in the grid-connected microgrid. Condition: The bidder is qualified in the hour-ahead auction. Completion of the local auction precedes dispatch of final power references and instructions to increase generation for the next hour. Scope: Hourly reverse-auction dispatch to qualified DER bidders in the grid-connected microgrid. The aggregator purchases the qualified amount of power from the DERs under the stated supply-shortfall condition. Scope: Purchase of qualified DER supply in the grid-connected microgrid's hour-ahead market when local supply is insufficient. Condition: Total supply is less than demand and some bidders are participating in the auction. Bidder agents' transmission of execution duration and generation amounts to actuator agents is conditional on their qualification in the auction. Scope: Actuator instructions implementing trades awarded through the microgrid's hour-ahead reverse auction. Condition: The bidder agents are qualified bidders after the auction organized by the aggregator agent.","constraints":[{"constraint_id":"v141-c-R007-C001","kind":"procedural","role":"core","statement":"Final local power allocations provide the power references according to which actuator agents operate generation units for the cleared exchange. Scope: Implementation of hourly allocations to qualified DER bidders in the grid-connected microgrid. Condition: The bidder is qualified in the hour-ahead auction.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["clearing.local","execution.energy_trade"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-E07","v141-b-g01-E20"]}],"evidence":[{"evidence_id":"v141-b-g01-E07","location":{"location_id":"src-1b3df4bc99-p03-c2r4__v141-a-M01-activation","page":3,"printed_page":null,"section":"IV. Proposed Methodology","anchor_text":"ty. grid infrastructure. In this paper, a set of industrial communi- ce cation protocols and physica","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"definition"},"source_text":"Sensor agents are responsible for system parameter measurements and sending the information to other agents or upper control areas if necessary. Actuator agents are responsible for operating generation units according to the power reference received from the bidder agents. Bidder agents inform the actuator agent duration and power generation amounts if they are qualified bidders after the auction process is organized by the aggregator agent."},{"evidence_id":"v141-b-g01-E20","location":{"location_id":"src-1b3df4bc99-p05-c1r3__v141-a-M01-activation","page":5,"printed_page":null,"section":"IV. Proposed Methodology","anchor_text":"to check whether qualiﬁed bidder’s submission is able to cover all demand. The ﬁrst qualiﬁed bidder ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"definition"},"source_text":"Once the auction process is over, the aggregator informs the final power references to the qualified bidders. Accordingly, bidder agents inform actuator agents to increase their generation for the next hour. The same process is repeated for each hour."}],"omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"activation","context_text":"Actuator instructions implementing trades awarded through the microgrid's hour-ahead reverse auction. | Hourly reverse-auction dispatch to qualified DER bidders in the grid-connected microgrid. | Implementation of hourly allocations to qualified DER bidders in the grid-connected microgrid. | Purchase of qualified DER supply in the grid-connected microgrid's hour-ahead market when local supply is insufficient.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-E07","v141-b-g01-E20","v141-b-g01-E21"]},"source_record":{"edge_id":"v141-c-R007-E001","source":"clearing.local","target":"execution.energy_trade","type":"links","constraint_ids":["v141-c-R007-C001"],"evidence_ids":["v141-b-g01-E07","v141-b-g01-E20"]},"paper_scope_note":"Registration, auction invitation, bid, eligibility, and final power command are checked separately; the utility base price differs from the DER private base price; the general single-winner and two-winner cases are not combined into the same condition."}});
